from collections import Counter

class Solution:
    def getLargestOutlier(self, nums: list[int]) -> int:
        total_sum = sum(nums)
        freq = Counter(nums)
        max_outlier = -float('inf')

        for x in nums:
            freq[x] -= 1
            rem = total_sum - x
            if rem % 2 == 0:
                target = rem // 2
                if freq[target] > 0:
                    if x > max_outlier:
                        max_outlier = x
            freq[x] += 1

        return max_outlier

class Solution {
public:
    int getLargestOutlier(vector<int>& nums) {
        long long totalSum = 0;
        unordered_map<int, int> freq;
        for (int x : nums) {
            totalSum += x;
            freq[x]++;
        }
        int maxOutlier = INT_MIN;
        for (int x : nums) {
            freq[x]--;
            long long rem = totalSum - x;
            if (rem % 2 == 0) {
                long long target = rem / 2;
                if (target >= INT_MIN && target <= INT_MAX && freq[target] > 0) {
                    maxOutlier = max(maxOutlier, x);
                }
            }
            freq[x]++;
        }
        return maxOutlier;
    }
};

class Solution {
    public int getLargestOutlier(int[] nums) {
        long totalSum = 0;
        Map<Integer, Integer> freq = new HashMap<>();
        for (int x : nums) {
            totalSum += x;
            freq.put(x, freq.getOrDefault(x, 0) + 1);
        }
        int maxOutlier = Integer.MIN_VALUE;
        for (int x : nums) {
            freq.put(x, freq.get(x) - 1);
            long rem = totalSum - x;
            if (rem % 2 == 0) {
                long target = rem / 2;
                if (target >= Integer.MIN_VALUE && target <= Integer.MAX_VALUE && freq.getOrDefault((int) target, 0) > 0) {
                    maxOutlier = Math.max(maxOutlier, x);
                }
            }
            freq.put(x, freq.get(x) + 1);
        }
        return maxOutlier;
    }
}

var getLargestOutlier = function(nums) {
    let totalSum = 0;
    const freq = new Map();
    for (const x of nums) {
        totalSum += x;
        freq.set(x, (freq.get(x) || 0) + 1);
    }
    let maxOutlier = -Infinity;
    for (const x of nums) {
        freq.set(x, freq.get(x) - 1);
        const rem = totalSum - x;
        if (rem % 2 === 0) {
            const target = rem / 2;
            if ((freq.get(target) || 0) > 0) {
                maxOutlier = Math.max(maxOutlier, x);
            }
        }
        freq.set(x, freq.get(x) + 1);
    }
    return maxOutlier;
};
